/* TCC MENU EXPERIENCE ENHANCEMENTS v2 */
(function initTccMenuExperience(){
  const start=()=>{
    const root=document.querySelector(".menu-content");
    const status=document.getElementById("menuSearchStatus");
    const searchInput=document.getElementById("menuSearch");
    if(!root||!searchInput)return;
    const originalFilter=window.filter;
    const updateSearchStatus=()=>{
      const active=document.querySelector(".menu-group.active");
      const visible=Array.from(root.querySelectorAll(".menu-group.active .m-item")).filter(item=>item.style.display!=="none");
      const q=searchInput.value.trim();
      if(status)status.textContent=q?visible.length+" matching item"+(visible.length===1?"":"s"):"";
    };
    if(typeof originalFilter==="function")window.filter=function(q){originalFilter(q);updateSearchStatus();};
    else searchInput.addEventListener("input",updateSearchStatus);
    searchInput.addEventListener("keydown",event=>{
      if(event.key==="Escape"){
        searchInput.value="";
        searchInput.dispatchEvent(new Event("input",{bubbles:true}));
        window.filter("");
      }
    });
    document.addEventListener("click",event=>{
      if(event.target.closest(".menu-tab")||event.target.closest(".food-tab")){
        requestAnimationFrame(updateSearchStatus);
      }
    });
    root.querySelectorAll(".m-photo-wrap").forEach(wrap=>{
      const img=wrap.querySelector(".m-photo");if(!img)return;
      const done=()=>{wrap.classList.remove("is-loading");if(img.naturalWidth)wrap.classList.add("is-loaded");};
      if(img.complete&&img.naturalWidth){wrap.classList.add("is-loaded");return;}
      wrap.classList.add("is-loading");
      img.addEventListener("load",done,{once:true});
      img.addEventListener("error",done,{once:true});
    });
  };
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",start,{once:true});else start();
})();

