function addTccMenuPhotos(){
  document.querySelectorAll('.menu-section .m-item').forEach(item=>{
    const title=item.querySelector('h3'), price=item.querySelector('strong');
    if(!title||!price||item.querySelector('.m-photo-wrap')) return;
    const cleanTitle=title.cloneNode(true);
    cleanTitle.querySelectorAll('.food-badge,.best-seller,.availability-status,[class*="badge"]').forEach(el=>el.remove());
    const name=cleanTitle.textContent.replace(/\s+/g,' ').trim();
    const photo=TCC_VERIFIED_PHOTOS[name];
    const wrap=document.createElement('div');
    wrap.className='m-photo-wrap'+(photo?'':' m-photo-placeholder-wrap');
    if(photo){
      const img=document.createElement('img');
      img.className='m-photo';
      // Crop only selected drink photos where the product is the focal point;
      // leave all other images in their existing contain mode.
      const productFocusedCrop=new Set(['Cappuccino','Orange Fizzy','Watermelon Fizzy','Iced Latte','Berry Iced Tea','Classic Matcha (Hot / Cold)','Strawberry Matcha']);
      if(productFocusedCrop.has(name)) img.classList.add('m-photo-product-crop');
      img.loading='lazy';
      img.decoding='async';
      img.fetchPriority='auto';
      img.sizes='(max-width: 699px) 50vw, (max-width: 999px) 33vw, 25vw';
      img.srcset=photo.url+' 400w, '+photo.large+' 800w';
      img.alt=name+' — TCC menu photo'; img.src=photo.url; img.tabIndex=0; img.setAttribute("role","button"); img.setAttribute("aria-haspopup","dialog"); img.setAttribute("aria-label","View "+name+" photo and details");
      img.addEventListener('error',()=>{
        wrap.classList.add('m-photo-placeholder-wrap');
        wrap.innerHTML='<div class="m-photo-placeholder" role="img" aria-label="Photo coming soon"><img class="m-photo-placeholder-logo" src="images/logo.png" alt="TCC – The Coffee Club"><strong class="m-photo-coming-soon" style="color:#173d31!important;-webkit-text-fill-color:#173d31!important">Photo Coming Soon</strong></div>';
      },{once:true});
      wrap.appendChild(img);
    }else{
      wrap.innerHTML='<div class="m-photo-placeholder" role="img" aria-label="Photo coming soon"><img class="m-photo-placeholder-logo" src="images/logo.png" alt="TCC – The Coffee Club"><strong class="m-photo-coming-soon" style="color:#173d31!important;-webkit-text-fill-color:#173d31!important">Photo Coming Soon</strong></div>';
    }
    item.insertBefore(wrap,item.firstChild);
    const info=document.createElement('div'); info.className='m-item-info';
    const sourceBlock=title.parentElement;
    sourceBlock.querySelectorAll('h3,p,.availability-status').forEach(el=>info.appendChild(el));
    sourceBlock.replaceWith(info);
  });
}
// Text / image menu view switch
(function initTccMenuViewSwitch(){
  const buttons=[...document.querySelectorAll("[data-menu-view]")];
  if(!buttons.length) return;
  function setMenuView(view){
    const textMode=view==="text";
    document.body.classList.toggle("menu-text-mode",textMode);
    buttons.forEach(button=>{
      const active=button.dataset.menuView===view;
      button.classList.toggle("is-active",active);
      button.setAttribute("aria-pressed",active?"true":"false");
    });
  }
  buttons.forEach(button=>button.addEventListener("click",()=>setMenuView(button.dataset.menuView)));
  setMenuView("image");
})();

// Tap any menu photo to view it larger; tap outside or close to return.
const tccImageLightbox=document.createElement("div");
tccImageLightbox.className="menu-image-lightbox";
tccImageLightbox.setAttribute("role","dialog");
tccImageLightbox.setAttribute("aria-modal","true");
tccImageLightbox.setAttribute("aria-label","Expanded menu photo");
tccImageLightbox.setAttribute("aria-labelledby","menuLightboxName");
tccImageLightbox.innerHTML='<button type="button" class="menu-image-lightbox-close" aria-label="Close expanded image">&times;</button><div class="menu-lightbox-card"><img alt="" /><div class="menu-lightbox-details"><h2 class="menu-lightbox-name" id="menuLightboxName"></h2><div class="menu-lightbox-bestseller" aria-label="Best Seller"><span class="crown" aria-hidden="true">♛</span><span>Best Seller</span></div><div class="menu-lightbox-new-arrival" aria-label="New Arrival"><span aria-hidden="true">✦</span><span>New Arrival</span></div><p class="menu-lightbox-description"></p><div class="menu-lightbox-spice" aria-live="polite"></div><div class="menu-lightbox-price"></div><div class="menu-lightbox-addons"><h3 class="menu-lightbox-addons-title">Available add-ons</h3><div class="menu-lightbox-addons-row"></div></div></div></div>';
document.body.appendChild(tccImageLightbox);
const tccLightboxImage=tccImageLightbox.querySelector("img");
const tccLightboxName=tccImageLightbox.querySelector(".menu-lightbox-name");
const tccLightboxDescription=tccImageLightbox.querySelector(".menu-lightbox-description");
const tccLightboxSpice=tccImageLightbox.querySelector(".menu-lightbox-spice");
const tccLightboxPrice=tccImageLightbox.querySelector(".menu-lightbox-price");
const tccLightboxAddons=tccImageLightbox.querySelector(".menu-lightbox-addons");
const tccLightboxAddonsRow=tccImageLightbox.querySelector(".menu-lightbox-addons-row");
const tccLightboxClose=tccImageLightbox.querySelector("button");
let tccLightboxTrigger=null;
function hideTccImageLightbox(){
  tccImageLightbox.classList.remove("is-open");
  tccLightboxImage.removeAttribute("src");
  document.body.style.overflow="";
  if(tccLightboxTrigger?.isConnected) tccLightboxTrigger.focus();
  tccLightboxTrigger=null;
}
function closeTccImageLightbox(){
  if(history.state&&history.state.tccImageLightbox){
    history.back();
  }else{
    hideTccImageLightbox();
  }
}
document.addEventListener("click",event=>{
  const photo=event.target.closest(".m-photo");
  if(photo){
    tccLightboxTrigger=photo;
    if(!tccImageLightbox.classList.contains("is-open")){
      history.pushState({tccImageLightbox:true},"",window.location.href);
    }
    tccLightboxImage.src=photo.currentSrc||photo.src;
    tccLightboxImage.alt=photo.alt||"Expanded menu photo";
    const item=photo.closest(".m-item");
    const heading=item?.querySelector("h3");
    const cleanHeading=heading?.cloneNode(true);
    cleanHeading?.querySelectorAll(".tcc-bestseller-badge,.tcc-new-arrival-badge,.food-badge,.availability-status").forEach(el=>el.remove());
    const name=cleanHeading?.textContent.replace(/\\s+/g," ").trim()||photo.alt||"Menu item";
    const isBestSeller=!!heading?.querySelector(".tcc-bestseller-badge");
    const isNewArrival=!!heading?.querySelector(".tcc-new-arrival-badge");
    const bestSellerBadge=tccImageLightbox.querySelector(".menu-lightbox-bestseller");
    bestSellerBadge?.classList.toggle("is-visible",isBestSeller);
    tccImageLightbox.querySelector(".menu-lightbox-new-arrival")?.classList.toggle("is-visible",isNewArrival);
    const price=item?.querySelector("strong")?.textContent.trim()||"";
    const description=item?[...item.querySelectorAll(".m-item-info p")].map(p=>p.textContent.trim()).filter(Boolean).join(" "):"";
    tccLightboxName.textContent=name;
    tccLightboxDescription.textContent=description;
    tccLightboxSpice.replaceChildren();
    const spiceLevel=item?.querySelector(".spice-level");
    if(spiceLevel){tccLightboxSpice.appendChild(spiceLevel.cloneNode(true));tccLightboxSpice.style.display="block";}
    else{tccLightboxSpice.style.display="none";}
    const section=item?.closest(".menu-section");
    const sectionName=section?.querySelector("h2")?.textContent.trim().toLowerCase()||"";
    const addonPanel=document.querySelector("[data-addon-panel] .addons-row");
    const hasAddons=sectionName.includes("pasta")&&!!addonPanel;
    tccLightboxAddonsRow.replaceChildren();
    if(hasAddons){
      addonPanel.querySelectorAll("span").forEach(addon=>tccLightboxAddonsRow.appendChild(addon.cloneNode(true)));
    }
    tccLightboxAddons.style.display=hasAddons?"block":"none";
    tccLightboxPrice.textContent=price;
    tccLightboxPrice.style.display=price?"inline-block":"none";
    tccImageLightbox.classList.add("is-open");
    document.body.style.overflow="hidden";
    tccLightboxClose.focus();
  }
});
tccLightboxClose.addEventListener("click",closeTccImageLightbox);
tccImageLightbox.addEventListener("click",event=>{
  if(event.target===tccImageLightbox) closeTccImageLightbox();
});
window.addEventListener("popstate",()=>{
  // Close the topmost menu overlay first; keep the menu page itself open.
  if(typeof foodSpotlight!=="undefined"&&foodSpotlight?.classList.contains("is-open")){
    closeFoodSpotlight(true);
    return;
  }
  if(tccImageLightbox.classList.contains("is-open")) hideTccImageLightbox();
});
document.addEventListener("keydown",event=>{
  if(event.target?.matches?.(".m-photo")&&(event.key==="Enter"||event.key===" ")){
    event.preventDefault();
    event.target.click();
    return;
  }
  if(!tccImageLightbox.classList.contains("is-open")) return;
  if(event.key==="Escape"){
    event.preventDefault();
    closeTccImageLightbox();
    return;
  }
  if(event.key==="Tab"){
    event.preventDefault();
    tccLightboxClose.focus();
  }
});

// Hold a menu photo to preview it temporarily; releasing the pointer restores the card.
(function initTccPressAndHoldPhotoPeek(){
  const peek=document.createElement("div");
  peek.className="menu-photo-peek";
  peek.setAttribute("aria-hidden","true");
  const preview=document.createElement("img");
  preview.alt="";
  const details=document.createElement("div");
  details.className="menu-photo-peek-details";
  const productName=document.createElement("div");
  productName.className="menu-photo-peek-name";
  const productPrice=document.createElement("div");
  productPrice.className="menu-photo-peek-price";
  details.append(productName,productPrice);
  peek.append(preview,details);
  document.body.appendChild(peek);
  let holdTimer=null,activePointer=null,startX=0,startY=0,openedByHold=false,suppressClickUntil=0;
  const HOLD_DELAY=280,MOVE_LIMIT=12;
  function clearHoldTimer(){if(holdTimer){clearTimeout(holdTimer);holdTimer=null;}}
  function closePeek(){
    clearHoldTimer();
    if(activePointer!==null&&openedByHold){
      try{if(peek.hasPointerCapture?.(activePointer))peek.releasePointerCapture(activePointer);}catch(e){}
    }
    peek.classList.remove("is-visible");
    peek.setAttribute("aria-hidden","true");
    preview.removeAttribute("src");
    activePointer=null;
    openedByHold=false;
  }
  function openPeek(photo){
    if(!photo?.src||photo.closest(".m-photo-placeholder-wrap"))return;
    const item=photo.closest(".m-item");
    const heading=item?.querySelector(".m-item-info h3, h3");
    const cleanHeading=heading?.cloneNode(true);
    cleanHeading?.querySelectorAll(".tcc-bestseller-badge,.tcc-new-arrival-badge,.food-badge,.availability-status").forEach(el=>el.remove());
    const name=cleanHeading?.textContent.replace(/\\s+/g," ").trim()||"";
    const price=item?.querySelector(".m-item > strong, .m-item-info + strong, strong");
    preview.src=photo.currentSrc||photo.src;
    preview.alt=name?name+" — enlarged TCC menu photo":"Enlarged TCC menu photo";
    productName.textContent=name;
    productPrice.textContent=price?.textContent.trim()||"";
    productPrice.hidden=!productPrice.textContent;
    peek.classList.add("is-visible");
    peek.setAttribute("aria-hidden","false");
    openedByHold=true;
  }
  document.addEventListener("pointerdown",event=>{
    const photo=event.target.closest?.(".m-photo");
    if(!photo||event.button!==0||tccImageLightbox.classList.contains("is-open"))return;
    clearHoldTimer();
    activePointer=event.pointerId;startX=event.clientX;startY=event.clientY;openedByHold=false;
    holdTimer=setTimeout(()=>{if(activePointer===event.pointerId)openPeek(photo);},HOLD_DELAY);
  },{passive:true});
  document.addEventListener("pointermove",event=>{
    if(activePointer!==event.pointerId)return;
    if(Math.hypot(event.clientX-startX,event.clientY-startY)>MOVE_LIMIT){
      clearHoldTimer();
      if(openedByHold)closePeek();
      else activePointer=null;
    }
  },{passive:true});
  function finishPointer(event){
    if(activePointer!==event.pointerId)return;
    const wasPeekOpen=openedByHold;
    clearHoldTimer();
    if(wasPeekOpen){suppressClickUntil=Date.now()+650;closePeek();}
    else activePointer=null;
  }
  document.addEventListener("pointerup",finishPointer,{passive:true});
  document.addEventListener("pointercancel",finishPointer,{passive:true});
  document.addEventListener("click",event=>{
    if(Date.now()<suppressClickUntil&&event.target.closest?.(".m-photo")){
      event.preventDefault();event.stopImmediatePropagation();
    }
  },true);
  document.addEventListener("contextmenu",event=>{
    if(event.target.closest?.(".m-photo"))event.preventDefault();
  });
  document.addEventListener("dragstart",event=>{
    if(event.target.closest?.(".m-photo"))event.preventDefault();
  });
  window.addEventListener("blur",closePeek);
})();


