const tabs=[...document.querySelectorAll(".menu-tab")], groups=[...document.querySelectorAll(".menu-group")], search=document.getElementById("menuSearch"), noResults=document.getElementById("noResults"), foodTabsWrap=document.getElementById("foodTabs");
let foodTabs=[];

function buildSubTabs(id){
  if(!foodTabsWrap) return;
  const group=document.getElementById(id);
  if(!group){ foodTabsWrap.classList.remove("visible"); return; }
  const sections=[...group.querySelectorAll(":scope > .menu-section")];
  foodTabsWrap.innerHTML="";
  const all=document.createElement("button");
  all.className="food-tab active";
  all.type="button";
  all.setAttribute("aria-pressed","true");
  all.dataset.foodTarget="all";
  all.textContent=id==="food"?"All Food":"All";
  foodTabsWrap.appendChild(all);
  if(id==="food"){
    const labels=[
      ["Soups","Soups"],
      ["Appetizers","Starters"],
      ["Pastas","Pasta"],
      ["Pizzas","Pizza"],
      ["Burgers","Burgers"],
      ["Sandwiches","Sandwiches"]
    ];
    labels.forEach(([target,label])=>{
      const b=document.createElement("button");
      b.className="food-tab";
      b.type="button";
      b.setAttribute("aria-pressed","false");
      b.dataset.foodTarget=target;
      b.textContent=label;
      foodTabsWrap.appendChild(b);
    });
  } else {
    sections.forEach(sec=>{
      const h=(sec.querySelector("h2")?.textContent||"").trim();
      if(!h) return;
      const b=document.createElement("button");
      b.className="food-tab";
      b.type="button";
      b.setAttribute("aria-pressed","false");
      b.dataset.foodTarget=h;
      b.textContent=h;
      foodTabsWrap.appendChild(b);
    });
  }
  foodTabs=[...foodTabsWrap.querySelectorAll(".food-tab")];
  foodTabs.forEach(t=>t.addEventListener("click",()=>jumpToSubcategory(t.dataset.foodTarget)));
  foodTabsWrap.classList.add("visible");
}

function syncFoodTabToScroll(){
  if(!foodTabsWrap || !foodTabsWrap.classList.contains("visible")) return;
  const active=document.querySelector(".menu-group.active");
  if(!active) return;
  const toolsBar=document.querySelector(".menu-tools");
  const anchor=(toolsBar?.getBoundingClientRect().bottom||0)+34;
  const sections=[...active.querySelectorAll(":scope > .menu-section")].filter(sec=>{
    const style=getComputedStyle(sec);
    return style.display!=="none" && sec.getClientRects().length>0;
  });
  if(!sections.length) return;
  let chosen=sections[0], best=Infinity;
  sections.forEach(sec=>{
    const rect=sec.getBoundingClientRect();
    const distance=rect.top<=anchor && rect.bottom>=anchor ? 0 : Math.abs(rect.top-anchor)+(rect.bottom<anchor?80:0);
    if(distance<best){best=distance;chosen=sec;}
  });
  const heading=(chosen.querySelector("h2")?.textContent||"").trim().toLowerCase();
  const matched=foodTabs.find(t=>{
    if(t.dataset.foodTarget==="all") return false;
    const target=t.dataset.foodTarget.toLowerCase();
    return heading===target || heading.includes(target) || target.includes(heading);
  });
  const next=matched || foodTabs.find(t=>t.dataset.foodTarget==="all");
  if(!next) return;
  foodTabs.forEach(t=>t.classList.toggle("active",t===next));
  const wrapRect=foodTabsWrap.getBoundingClientRect(), tabRect=next.getBoundingClientRect();
  if(tabRect.left<wrapRect.left+8) foodTabsWrap.scrollLeft-=wrapRect.left-tabRect.left+12;
  else if(tabRect.right>wrapRect.right-8) foodTabsWrap.scrollLeft+=tabRect.right-wrapRect.right+12;
}

let foodScrollTick=false;
window.addEventListener("scroll",()=>{
  if(foodScrollTick) return;
  foodScrollTick=true;
  requestAnimationFrame(()=>{syncFoodTabToScroll();foodScrollTick=false;});
},{passive:true});
window.addEventListener("resize",syncFoodTabToScroll);

function jumpToSubcategory(target){
  if(!target) return;
  foodTabs.forEach(x=>{const active=x.dataset.foodTarget===target;x.classList.toggle("active",active);x.setAttribute("aria-pressed",String(active));});
  const active=document.querySelector(".menu-group.active");
  if(!active) return;
  if(target==="all"){
    const first=active.querySelector(".menu-section");
    if(first){
      const toolsBar=document.querySelector(".menu-tools");
      const jumpAll=()=>{
        const desired=(toolsBar?.getBoundingClientRect().bottom||0)+12;
        const delta=first.getBoundingClientRect().top-desired;
        if(Math.abs(delta)>2) window.scrollBy({top:delta,behavior:"smooth"});
      };
      jumpAll();
      setTimeout(jumpAll,450);
    }
    return;
  }
  const section=[...active.querySelectorAll(":scope > .menu-section")].find(sec=>
    (sec.querySelector("h2")?.textContent||"").trim().toLowerCase()===target.toLowerCase()
  ) || [...active.querySelectorAll(":scope > .menu-section")].find(sec=>
    (sec.querySelector("h2")?.textContent||"").toLowerCase().includes(target.toLowerCase())
  );
  if(!section) return;
  const panel=document.querySelector("[data-addon-panel]");
  if(panel) panel.style.display="block";
  const toolsBar=document.querySelector(".menu-tools");
  const jump=()=>{
    const heading=section.querySelector("h2")||section;
    const desired=(toolsBar?.getBoundingClientRect().bottom||0)+12;
    const delta=heading.getBoundingClientRect().top-desired;
    if(Math.abs(delta)>2) window.scrollBy({top:delta,behavior:"smooth"});
  };
  jump();
  setTimeout(jump,450);
  setTimeout(jump,900);
}

/* TCC Drink Finder: match actual available menu drinks to customer preferences. */
const tccDrinkPicker=document.getElementById("tccDrinkPicker");
const tccDrinkResult=document.getElementById("tccDrinkPickResult");
let tccCurrentDrink=null;
let tccQuizStep=0;
let tccQuizAnswers={mood:null,temperature:null,sweetness:null,flavour:null};
function tccQuestionsForAnswers(){
 const pool=tccEligibleDrinks().filter(x=>x.profile);
 const answers=tccQuizAnswers;
 const dimensions=[
  {key:"mood",weight:5,title:"What kind of drink are you in the mood for?",hint:"Choose a drink style to get started.",labels:{coffee:"Coffee",tea:"Tea",fizzy:"Refreshing drinks",matcha:"Matcha",shake:"Shakes"}},
  {key:"temperature",weight:4,title:"Would you prefer it hot or cold?",hint:"We'll narrow it down to the drinks that suit you.",labels:{hot:"Hot",cold:"Cold",any:"Either"}},
  {key:"sweetness",weight:3,title:"How sweet do you like your drink?",hint:"Choose the sweetness you usually enjoy.",labels:{none:"Not sweet",light:"Lightly sweet",medium:"Medium sweet",sweet:"Sweet"}},
  {key:"flavour",weight:2,title:"Which flavour sounds best?",hint:"One more detail can help us find a closer match.",labels:{coffee:"Coffee",creamy:"Smooth & creamy",chocolate:"Chocolate",fruity:"Fruity",floral:"Floral",tea:"Tea"}}
 ];
 const questions=[];let candidates=pool.slice(),used=[];
 for(let step=0;step<4;step++){
  const ranked=dimensions.filter(d=>!used.includes(d.key)).map(d=>{
   const values=[...new Set(candidates.map(x=>d.key==="flavour"?x.profile.flavours:x.profile[d.key]).flat().filter(Boolean))];
   const splits=values.length;
   const distribution=values.map(value=>candidates.filter(x=>d.key==="flavour"?x.profile.flavours.includes(value):x.profile[d.key]===value).length).filter(Boolean);
   const total=distribution.reduce((sum,n)=>sum+n,0);
   const entropy=total?distribution.reduce((sum,n)=>{const p=n/total;return sum-p*Math.log2(p);},0):0;
   return {...d,values,utility:splits>1?entropy*d.weight:0};
  }).filter(d=>d.utility>0).sort((a,b)=>b.utility-a.utility);
  if(!ranked.length)break;
  const d=ranked[0];used.push(d.key);
  const values=d.values;
  const opts=values.map(value=>[value,d.labels[value]||value]);
  questions.push({key:d.key,question:d.title,hint:d.hint,options:opts});
  const chosen=answers[d.key];
  if(chosen)candidates=candidates.filter(x=>d.key==="flavour"?x.profile.flavours.includes(chosen):x.profile[d.key]===chosen);
 }
 return questions;
}
