function tccCleanDrinkName(item){
 const h=item.querySelector("h3");
 return (h?.cloneNode(true).textContent||"").replace(/Best Seller|NEW ARRIVAL|♛/gi,"").replace(/\s+/g," ").trim();
}
function tccEligibleDrinks(){
 return ["coffee","refreshers-and-tea","signatures"].flatMap(groupId=>{
  const group=document.getElementById(groupId);if(!group)return [];
  return [...group.querySelectorAll(".m-item")].filter(item=>
   !item.querySelector(".availability-status")&&!/sold\s*out|temporarily unavailable/i.test(item.textContent)
  ).map(item=>{
   const name=tccCleanDrinkName(item);
   return {item,name,price:[...item.children].find(el=>el.matches("strong"))?.textContent.trim()||"",profile:tccDrinkProfiles[name]||null};
  });
 }).filter(x=>x.name);
}
function tccRenderQuizStep(){
 const questions=tccQuestionsForAnswers();
 tccQuizStep=Math.min(tccQuizStep,questions.length-1);
 const q=questions[tccQuizStep],options=document.getElementById("tccQuizOptions");
 document.getElementById("tccQuizStepMeta").textContent="STEP "+(tccQuizStep+1)+" OF "+questions.length;
 document.getElementById("tccQuizProgressFill").style.width=((tccQuizStep+1)/questions.length*100)+"%";
 document.getElementById("tccQuizQuestion").textContent=q.question;
 const hint=document.getElementById("tccQuizHint");if(hint)hint.textContent=q.hint||"";
 options.replaceChildren();
 q.options.forEach(([value,label])=>{
  const b=document.createElement("button");b.type="button";b.className="tcc-quiz-option";b.textContent=label;
  b.setAttribute("aria-pressed",String(tccQuizAnswers[q.key]===value));
  b.addEventListener("click",()=>{
   const prior=tccQuizAnswers[q.key];tccQuizAnswers[q.key]=value;
   if(prior!==value){
    const order=["mood","temperature","sweetness","flavour"];
    order.slice(order.indexOf(q.key)+1).forEach(key=>{tccQuizAnswers[key]=null;});
   }
   options.querySelectorAll("button").forEach(x=>x.setAttribute("aria-pressed",String(x===b)));
   document.getElementById("tccQuizNext").disabled=false;
   document.getElementById("tccQuizNext").textContent=tccQuizStep===questions.length-1?"Find my drink":"Next";
  });
  options.appendChild(b);
 });
 document.getElementById("tccQuizBack").disabled=tccQuizStep===0;
 const next=document.getElementById("tccQuizNext");
 next.disabled=!tccQuizAnswers[q.key];
 next.textContent=tccQuizStep===questions.length-1?"Find my drink":"Next";
}
function tccScoreDrink(drink){
 const p=drink.profile,a=tccQuizAnswers;
 let score=0,answered=0,hardMatch=true;
 // Drink type and temperature are strong constraints.
 if(a.mood){answered++;if(p.mood===a.mood)score+=32;else{score-=36;hardMatch=false;}}
 if(a.temperature){
  answered++;
  if(p.temperature===a.temperature)score+=26;
  else if(p.temperature==="any")score+=18;
  else{score-=32;hardMatch=false;}
 }
 // Sweetness is a gradient: a nearby level can still be a reasonable fit.
 const sweetnessOrder={none:0,light:1,medium:2,sweet:3};
 if(a.sweetness&&p.sweetness){
  answered++;
  const distance=Math.abs(sweetnessOrder[a.sweetness]-sweetnessOrder[p.sweetness]);
  score+=distance===0?18:distance===1?7:-5;
 }
 if(a.flavour){answered++;score+=p.flavours.includes(a.flavour)?20:-3;}
 // Bestseller status is only a tiny tie-breaker, never the main match signal.
 if(drink.item?.querySelector(".tcc-bestseller-badge"))score+=1;
 return {score,answered,hardMatch};
}
function tccDrinkSimilarity(a,b){
 const pa=a.profile,pb=b.profile;let same=0,total=0;
 ["mood","temperature","sweetness"].forEach(key=>{
  if(pa[key]&&pb[key]){total++;if(pa[key]===pb[key]||(key==="temperature"&&(pa[key]==="any"||pb[key]==="any")))same++;}
 });
 const fa=pa.flavours||[],fb=pb.flavours||[];
 if(fa.length&&fb.length){total++;if(fa.some(x=>fb.includes(x)))same++;}
 return total?same/total:0;
}
function tccAlternativeNote(drink,best,index){
 if(index===0)return "Closest alternative to your choices";
 return tccDrinkSimilarity(drink,best)<=0.5?"A different taste to explore":"Another drink that fits your mood";
}
function tccDrinkReason(drink){
 const a=tccQuizAnswers,reasons=[];
 if(a.mood)reasons.push(({coffee:"coffee",tea:"tea",fizzy:"refreshing drinks",matcha:"matcha",shake:"shakes"}[a.mood]||"your chosen drink style"));
 if(a.temperature)reasons.push(a.temperature==="hot"?"a hot drink":a.temperature==="cold"?"a cold drink":"either temperature");
 if(a.sweetness)reasons.push(({none:"no added sweetness",light:"light sweetness",medium:"balanced sweetness",sweet:"a sweeter taste"}[a.sweetness]));
 if(a.flavour)reasons.push(({coffee:"coffee flavour",creamy:"creamy texture",chocolate:"chocolate",fruity:"fruity flavours",floral:"floral notes",tea:"tea flavour"}[a.flavour]||a.flavour));
 return reasons.length?"Matched to your preference for "+reasons.slice(0,3).join(", ")+".":"A recommended drink from the available TCC menu.";
}
function tccShowDrinkCard(drink){
 tccCurrentDrink=drink;
 document.getElementById("tccDrinkPickName").textContent=drink.name;
 document.getElementById("tccDrinkPickPrice").textContent=drink.price;
 const description=drink.item.querySelector(".m-item-info p, p");
 document.getElementById("tccDrinkPickDescription").textContent=description?.textContent.trim()||"A favourite from the TCC drinks menu.";
 document.getElementById("tccDrinkPickWhy").textContent=tccDrinkReason(drink);
 const photoBox=document.getElementById("tccDrinkPickPhoto");
 photoBox.replaceChildren();
 const verifiedPhoto=TCC_VERIFIED_PHOTOS[drink.name];
 const sourcePhoto=drink.item.querySelector(".m-photo-wrap");
 let photoWrap;
 if(verifiedPhoto){
  // Some menu entries intentionally have no inline photo markup. Build the
  // recommendation image directly from the verified photo map in that case.
  photoWrap=sourcePhoto?sourcePhoto.cloneNode(true):document.createElement("div");
  photoWrap.classList.add("m-photo-wrap");
  photoWrap.style.width="100%";
  photoWrap.style.height="100%";
  photoWrap.style.aspectRatio="1 / 1";
  let img=photoWrap.querySelector("img");
  if(!img){img=document.createElement("img");photoWrap.replaceChildren(img);}
  const normalizePhotoPath=value=>{
   if(!value||value.startsWith("data:")||/^https?:\/\//i.test(value))return value;
   return value.startsWith("/")?value:"/"+value.replace(/^\.\/+/, "");
  };
  const smallUrl=normalizePhotoPath(verifiedPhoto.url);
  const largeUrl=normalizePhotoPath(verifiedPhoto.large);
  img.removeAttribute("srcset");
  img.removeAttribute("sizes");
  img.src=smallUrl;
  if(!smallUrl.startsWith("data:")&&largeUrl){
   img.srcset=smallUrl+" 400w, "+largeUrl+" 800w";
   img.sizes="(max-width: 600px) 112px, 180px";
  }
  img.classList.remove("tcc-photo-ready");
  img.addEventListener("load",()=>img.classList.add("tcc-photo-ready"),{once:true});
  img.loading="eager";
  img.decoding="async";
  img.fetchPriority="high";
  img.style.cssText="display:block;width:100%;height:100%;object-fit:cover;object-position:center";
  img.alt=drink.name+" — TCC drink recommendation";
  if(img.complete&&img.naturalWidth>0)img.classList.add("tcc-photo-ready");
  img.onerror=()=>{
   img.removeAttribute("srcset");
   img.removeAttribute("sizes");
   photoWrap.classList.add("is-photo-missing");
   img.remove();
   photoWrap.innerHTML='<div class="m-photo-placeholder"><strong>Photo Coming Soon</strong></div>';
  };
  photoBox.appendChild(photoWrap);
 }else if(sourcePhoto){
  photoWrap=sourcePhoto.cloneNode(true);
  photoWrap.style.width="100%";
  photoWrap.style.height="100%";
  photoWrap.style.aspectRatio="1 / 1";
  const img=photoWrap.querySelector("img");
  if(img){
   const original=img.currentSrc||img.src||img.getAttribute("data-src");
   if(original)img.src=original.startsWith("data:")||/^https?:\/\//i.test(original)?original:(original.startsWith("/")?original:"/"+original.replace(/^\.\/+/, ""));
   img.removeAttribute("srcset");
   img.removeAttribute("sizes");
   img.classList.remove("tcc-photo-ready");
   img.addEventListener("load",()=>img.classList.add("tcc-photo-ready"),{once:true});
   img.loading="eager";
   img.decoding="async";
   img.style.cssText="display:block;width:100%;height:100%;object-fit:cover;object-position:center";
   img.alt=drink.name+" — TCC drink recommendation";
   if(img.complete&&img.naturalWidth>0)img.classList.add("tcc-photo-ready");
   img.onerror=()=>{photoWrap.innerHTML='<div class="m-photo-placeholder"><strong>Photo Coming Soon</strong></div>';};
  }
  photoBox.appendChild(photoWrap);
 }else{
  photoBox.innerHTML='<div class="m-photo-placeholder"><strong>Photo Coming Soon</strong></div>';
 }
}
function tccPickMatchedDrink(){
 const eligible=tccEligibleDrinks().filter(x=>x.profile);
 const result=tccDrinkResult;
 const list=document.getElementById("tccDrinkAlternativeList");list.replaceChildren();
 if(!eligible.length){
  document.getElementById("tccQuizQuestion").textContent="Let's try another combination.";
  document.getElementById("tccQuizHint").textContent="We couldn't find a close match in the available drinks. Change an answer or explore the drinks menu.";
  document.getElementById("tccQuizOptions").style.display="none";
  document.querySelector(".tcc-quiz-controls").style.display="none";
  result.classList.add("is-visible");return;
 }
 const ranked=eligible.map(x=>({...x,...tccScoreDrink(x)})).sort((a,b)=>b.score-a.score);
 // Respect selected drink type and temperature whenever the menu has an exact fit.
 const strictPool=ranked.filter(x=>x.hardMatch);
 const pool=strictPool.length?strictPool:ranked;
 const chosen=pool[0];
 const remaining=pool.filter(x=>x.name!==chosen.name);
 const closeMatch=remaining.slice().sort((a,b)=>{
  const diff=b.score-a.score;
  if(Math.abs(diff)>8)return diff;
  return tccDrinkSimilarity(b,chosen)-tccDrinkSimilarity(a,chosen);
 })[0];
 const discovery=remaining.filter(x=>x.name!==closeMatch?.name).sort((a,b)=>{
  const diversity=tccDrinkSimilarity(a,chosen)-tccDrinkSimilarity(b,chosen);
  if(Math.abs(diversity)>0.05)return diversity;
  return b.score-a.score;
 })[0];
 const alternatives=[closeMatch,discovery].filter(Boolean);
 tccShowDrinkCard(chosen);
 alternatives.forEach((drink,index)=>{
  const card=document.createElement("button");card.type="button";card.className="tcc-drink-alternative";
  const name=document.createElement("strong");name.textContent=drink.name;
  const price=document.createElement("span");price.textContent=drink.price;
  const note=document.createElement("small");note.textContent=tccAlternativeNote(drink,chosen,index);
  const top=document.createElement("span");top.className="tcc-drink-alternative-top";top.append(name,price);
  card.append(top,note);
  card.addEventListener("click",()=>{
   tccShowDrinkCard(drink);
   list.querySelectorAll("button").forEach(x=>x.classList.toggle("is-selected",x===card));
  });
  list.appendChild(card);
 });
 document.getElementById("tccQuizStepMeta").textContent="YOUR TCC DRINK PICKS";
 document.getElementById("tccQuizProgressFill").style.width="100%";
 document.getElementById("tccQuizQuestion").textContent="Here are your best matches.";
 document.getElementById("tccQuizHint").textContent="We matched your answers with drinks currently available at TCC.";
 document.getElementById("tccQuizOptions").style.display="none";
 document.querySelector(".tcc-quiz-controls").style.display="none";
 document.getElementById("tccQuizRestart").textContent="Start again";
 result.classList.add("is-visible");
 requestAnimationFrame(()=>result.scrollIntoView({behavior:"smooth",block:"start"}));
}
