function showGroup(id,scrollToCategory=true){
  tabs.forEach(t=>{const active=t.dataset.target===id;t.classList.toggle("active",active);t.setAttribute("aria-pressed",String(active));});
  groups.forEach(g=>g.classList.toggle("active",g.id===id));
  const intro=document.getElementById("menuCategoryIntro");
  const copy={
    coffee:["01 · COFFEE & TEA","Slow down. Sip well.","Classic brews, cold favourites and everyday comforts."],
    "refreshers-and-tea":["02 · REFRESHERS","Bright. Cold. Refreshing.","Iced teas, coolers and South Indian favourites."],
    signatures:["03 · SIGNATURES","Made the TCC way.","Matcha, pour-over and house favourites."],
    food:["04 · FOOD","Good food, no fuss.","Soups, starters, pasta, pizzas, burgers and sandwiches, all in one place."],
    "ice-creams":["05 · ICE CREAMS","A little scoop of joy.","Classic flavours and frozen favourites."],
    desserts:["06 · DESSERTS","Save room for something sweet.","Cakes, dessert tins and indulgent jars."]
  }[id];
  if(intro&&copy){intro.querySelector(".category-kicker").textContent=copy[0];intro.querySelector("h2").textContent=copy[1];intro.querySelector("span").textContent=copy[2];}
  syncTccDrinkPicker();
  buildSubTabs(id);
  search.value="";
  filter("");
  syncPastaAddon();
  if(scrollToCategory){
    const menuTools=document.querySelector(".menu-tools");
    const categoryIntro=document.getElementById("menuCategoryIntro");
    const resetMenuScroll=()=>{
      if(!categoryIntro)return;
      const stickyHeight=menuTools ? menuTools.getBoundingClientRect().height : 0;
      categoryIntro.style.scrollMarginTop=(stickyHeight+8)+"px";
      // Keep category switching anchored below the sticky menu navigation.
      categoryIntro.scrollIntoView({block:"start",inline:"nearest",behavior:"instant"});
    };
    resetMenuScroll();
    requestAnimationFrame(resetMenuScroll);
    requestAnimationFrame(()=>requestAnimationFrame(resetMenuScroll));
  }
}
const foodSpotlight=document.getElementById("foodSpotlight");
const foodSpotlightSeenKey="tcc-chefs-special-tuscan-honey-chicken-v1";
let foodSpotlightPending=false;
function openFoodSpotlight(){
  if(!foodSpotlight) return false;
  let seen=false;
  try{seen=sessionStorage.getItem(foodSpotlightSeenKey)==="1";}catch(e){}
  if(seen) return false;
  foodSpotlightPending=true;
  // Add a lightweight history entry so Android/iOS Back dismisses this
  // promotion instead of navigating away from the menu page.
  if(!history.state?.tccFoodSpotlight){
    history.pushState({...history.state,tccFoodSpotlight:true},"",window.location.href);
  }
  foodSpotlight.classList.add("is-open");
  foodSpotlight.setAttribute("aria-hidden","false");
  document.body.style.overflow="hidden";
  try{sessionStorage.setItem(foodSpotlightSeenKey,"1");}catch(e){}
  document.getElementById("foodSpotlightExplore")?.focus();
  return true;
}
function closeFoodSpotlight(fromPopState=false){
  if(!foodSpotlight||!foodSpotlight.classList.contains("is-open")) return;
  // For an explicit close button/backdrop tap, consume the modal's history
  // entry. The popstate path closes directly and must not call history.back().
  if(!fromPopState&&history.state?.tccFoodSpotlight){
    history.back();
    return;
  }
  foodSpotlight.classList.remove("is-open");
  foodSpotlight.setAttribute("aria-hidden","true");
  document.body.style.overflow="";
  if(foodSpotlightPending){foodSpotlightPending=false;showGroup("food");}
}
document.getElementById("foodSpotlightExplore")?.addEventListener("click",closeFoodSpotlight);
document.getElementById("foodSpotlightClose")?.addEventListener("click",closeFoodSpotlight);
foodSpotlight?.addEventListener("click",e=>{if(e.target===foodSpotlight) closeFoodSpotlight();});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&foodSpotlight?.classList.contains("is-open")) closeFoodSpotlight();});
tabs.forEach(t=>t.addEventListener("click",()=>{
  if(t.dataset.target==="food"&&openFoodSpotlight()) return;
  showGroup(t.dataset.target);
}));
document.querySelectorAll("[data-fav-target]").forEach(a=>a.remove());

function filter(q){
  q=q.toLowerCase().trim();
  let found=0;
  const active=document.querySelector(".menu-group.active");
  if(!active) return;
  // No active food-filter controls are present in this menu build; keep category/search filtering functional without calling missing helpers.
  if(q){
    groups.forEach(g=>{
      let groupFound=0;
      g.querySelectorAll(".menu-section").forEach(sec=>{
        if(sec.hasAttribute("data-menu-paused")){sec.style.display="none";return;}
        let sectionFound=0;
        sec.querySelectorAll(".m-item").forEach(item=>{
          const matchesText=item.textContent.toLowerCase().includes(q);
          const ok=matchesText;
          item.style.setProperty("display",ok?"flex":"none","important");
          if(ok)sectionFound++;
        });
        sec.style.display=sectionFound?"block":"none";
        groupFound+=sectionFound;
      });
      g.classList.toggle("active",groupFound>0);
      found+=groupFound;
    });
    tabs.forEach(t=>{const active=!!groups.find(g=>g.id===t.dataset.target)?.classList.contains("active");t.classList.toggle("active",active);t.setAttribute("aria-pressed",String(active));});
    if(foodTabsWrap) foodTabsWrap.classList.remove("visible");
  } else {
    groups.forEach(g=>g.classList.toggle("active",g===active));
    active.querySelectorAll(".menu-section").forEach(sec=>{
      if(sec.hasAttribute("data-menu-paused")){sec.style.display="none";return;}
      let sectionFound=0;
      sec.querySelectorAll(".m-item").forEach(item=>{
        const ok=true;
        item.style.setProperty("display",ok?"flex":"none","important");
        if(ok)sectionFound++;
      });
      sec.style.display=sectionFound?"block":"none";
      found+=sectionFound;
    });
    buildSubTabs(active.id);
  }
  noResults.style.display=found?"none":"block";
  // No syncMenuFilterUI helper exists in this menu build; avoid aborting filter/navigation.
  syncPastaAddon();
  syncTccDrinkPicker();
}
search.addEventListener("input",e=>{
  const q=e.target.value.trim();
  search.classList.toggle("global-search-active",!!q);
  filter(q);
});
