/* One-time photo reveal only — no parallax, zoom or scroll movement. */
function initTccScrollPhotography(){
  const images=[...document.querySelectorAll(".menu-group .m-photo-wrap .m-photo")];
  if(!images.length)return;
  const reveal=img=>img.classList.add("tcc-photo-ready");
  if(window.matchMedia("(prefers-reduced-motion: reduce)").matches||!("IntersectionObserver" in window)){
    images.forEach(reveal);return;
  }
  const observer=new IntersectionObserver(entries=>{
    entries.forEach(entry=>{
      if(entry.isIntersecting){reveal(entry.target);observer.unobserve(entry.target);}
    });
  },{root:null,rootMargin:"40px 0px",threshold:0.05});
  images.forEach(img=>observer.observe(img));
}



/* TCC SPICE LEVELS — APPROVED DRAFT
   Ratings are maintained against exact menu item names. */
document.addEventListener("DOMContentLoaded", function addTccSpiceLevels(){
  const spiceRatings = {
    "Hearty Minestrone Soup":1,
    "Creamy Mushroom Soup":0,
    "French Fries Classic":1,
    "Peri Peri French Fries":4,
    "Butter Garlic Mushroom":3,
    "Potato Cheese Balls":2,
    "Corn Ribs":3,
    "Butter Garlic Prawns":3,
    "Fried Chicken Strips":2,
    "Butter Garlic Chicken":3,
    "Tuscan Honey Chicken":4,
    "Chicken Alfredo Bliss":1,
    "Fettuccine Aglio Olio":2,
    "Fettuccine Alfredo":2,
    "Penne Arrabbiata":3,
    "Penne Rossa":1,
    "Penne Alfredo":0,
    "Fettuccine Al Pesto":1,
    "Mac & Cheese (Veg)":0,
    "Italian Margherita":1,
    "The Farmer's Pizza":2,
    "Pizza Verde":2,
    "Pesto Pizza":1,
    "BBQ Chicken Pizza":1,
    "Pesto Chicken Pizza":1,
    "Chicken Pizzaiola":2,
    "Mushroom Burger":1,
    "Grilled Paneer Burger":2,
    "Grilled Chicken Burger":1,
    "Crispy Chicken Burger":2,
    "Cheese Grilled Sandwich":1,
    "Bombay Street Sandwich":2,
    "Crispy Chicken Sandwich":2,
    "Grilled Chicken Sandwich":2,
  };
  const labels = ["No spice","Very mild","Mild","Medium hot","Hot","Extra hot"];
  document.querySelectorAll(".menu-section .m-item").forEach(item=>{
    const heading=item.querySelector("h3");
    if(!heading || item.querySelector(".spice-level")) return;
    const cleanHeading=heading.cloneNode(true);
    cleanHeading.querySelectorAll(".tcc-bestseller-badge,.tcc-new-arrival-badge,.food-badge,.availability-status").forEach(el=>el.remove());
    const name=cleanHeading.textContent.replace(/\s+/g," ").trim();
    if(!Object.prototype.hasOwnProperty.call(spiceRatings,name)) return;
    const level=spiceRatings[name];
    const indicator=document.createElement("div");
    indicator.className="spice-level";
    indicator.setAttribute("aria-label","Spice level "+level+" out of 5: "+labels[level]);
    const chillies=level ? "🌶️".repeat(level) : "";
    indicator.innerHTML='<span class="spice-chillies" aria-hidden="true">'+chillies+'</span><span class="spice-copy">Spice '+level+'/5 · '+labels[level]+'</span>';
    const info=item.querySelector(".m-item-info")||heading.parentElement;
    const description=info.querySelector("p");
    if(description) description.insertAdjacentElement("afterend",indicator);
    else heading.insertAdjacentElement("afterend",indicator);
  });
});